const query = $input.first().json.query ?? {};
const generationId = typeof query.generationId === 'string' ? query.generationId.trim() : '';
const recipeId = typeof query.recipeId === 'string' ? query.recipeId.trim() : '';
const view = typeof query.view === 'string' ? query.view.trim().toLowerCase() : '';
const cuisineStyle = typeof query.cuisine === 'string' ? query.cuisine.trim().toLowerCase() : '';
const sort = typeof query.sort === 'string' ? query.sort.trim().toLowerCase() : 'latest';
const page = Number(query.page ?? 1);
const pageSize = Number(query.pageSize ?? 20);
const generationIdPattern = /^[a-zA-Z0-9_-]{1,100}$/;
const recipeIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const cuisineStyles = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const sortOrders = ['latest', 'likes'];
const isListLookup = view === 'list';
const hasOneLookupValue = Boolean(generationId) !== Boolean(recipeId);
const isGenerationLookup = Boolean(generationId);
const isValidListLookup = isListLookup
  && !generationId
  && !recipeId
  && (!cuisineStyle || cuisineStyles.includes(cuisineStyle))
  && sortOrders.includes(sort)
  && Number.isInteger(page)
  && page >= 1
  && Number.isInteger(pageSize)
  && pageSize >= 1
  && pageSize <= 20;
const isValidDirectLookup = !view
  && hasOneLookupValue
  && (isGenerationLookup ? generationIdPattern.test(generationId) : recipeIdPattern.test(recipeId));

return [{
  json: {
    isValid: isValidListLookup || isValidDirectLookup,
    lookupType: isListLookup ? 'list' : isGenerationLookup ? 'generation' : 'recipe',
    filterColumn: isGenerationLookup ? 'generation_id' : 'id',
    filterValue: isGenerationLookup ? generationId : recipeId,
    cuisineStyle: cuisineStyle || null,
    page,
    pageSize,
    sort,
  },
}];

const listRequest = $('Validate lookup request').first().json;
const rawResponse = $input.first().json;
const listResult = Array.isArray(rawResponse) ? rawResponse[0] : rawResponse;
const storedRecipes = Array.isArray(listResult?.recipes) ? listResult.recipes : [];

function mapRecipe(recipe) {
  return {
    id: recipe.id,
    generationId: recipe.generation_id,
    createdAt: recipe.created_at,
    title: recipe.title,
    summary: recipe.summary,
    cuisineStyle: recipe.cuisine_style,
    dietPreference: recipe.diet_preference,
    cookingTimeCategory: recipe.cooking_time_category,
    cookingTimeMinutes: recipe.cooking_time_minutes,
    portionCount: recipe.portion_count,
    cookingPeopleCount: recipe.cooking_people_count,
    usedIngredientPercentage: recipe.used_ingredient_percentage,
    availableIngredients: recipe.available_ingredients,
    additionalIngredients: recipe.additional_ingredients,
    nutritionPerPortion: recipe.nutrition_per_portion,
    nutritionTotal: recipe.nutrition_total,
    steps: recipe.steps,
    imageUrl: recipe.image_url,
    likesCount: recipe.likes_count,
    isPublic: recipe.is_public,
  };
}

const recipes = storedRecipes
  .filter(recipe => recipe && typeof recipe.id === 'string')
  .map(mapRecipe);
const totalItems = Number(listResult?.total_items ?? 0);
const totalPages = totalItems === 0 ? 0 : Math.ceil(totalItems / listRequest.pageSize);

return [{
  json: {
    responseBody: {
      success: true,
      recipes,
      pagination: {
        page: listRequest.page,
        pageSize: listRequest.pageSize,
        totalItems,
        totalPages,
      },
    },
  },
}];

const lookup = $('Validate lookup request').first().json;
const storedRecipes = $input
  .all()
  .flatMap(item => (Array.isArray(item.json) ? item.json : [item.json]))
  .filter(recipe => recipe && typeof recipe.id === 'string');

function mapRecipe(recipe) {
  return {
    id: recipe.id,
    generationId: recipe.generation_id,
    createdAt: recipe.created_at,
    title: recipe.title,
    summary: recipe.summary,
    cuisineStyle: recipe.cuisine_style,
    dietPreference: recipe.diet_preference,
    cookingTimeCategory: recipe.cooking_time_category,
    cookingTimeMinutes: recipe.cooking_time_minutes,
    portionCount: recipe.portion_count,
    cookingPeopleCount: recipe.cooking_people_count,
    usedIngredientPercentage: recipe.used_ingredient_percentage,
    availableIngredients: recipe.available_ingredients,
    additionalIngredients: recipe.additional_ingredients,
    nutritionPerPortion: recipe.nutrition_per_portion,
    nutritionTotal: recipe.nutrition_total,
    steps: recipe.steps,
    imageUrl: recipe.image_url,
    likesCount: recipe.likes_count,
    isPublic: recipe.is_public,
  };
}

const recipes = storedRecipes.map(mapRecipe);
const isGenerationLookup = lookup.lookupType === 'generation';
const found = isGenerationLookup ? recipes.length === 3 : recipes.length === 1;
const responseBody = found
  ? isGenerationLookup
    ? { success: true, generationId: lookup.filterValue, recipes }
    : { success: true, recipe: recipes[0] }
  : {
      success: false,
      code: isGenerationLookup ? 'GENERATION_NOT_FOUND' : 'RECIPE_NOT_FOUND',
      message: isGenerationLookup
        ? 'The requested recipe generation could not be found.'
        : 'The requested recipe could not be found.',
    };

return [{ json: { found, responseBody } }];
